// Des: Tests for human timing: range, tail, persona, fatigue
// Flo: seeded generator > many samples > assert bounds, spread, tail share, stability
// I/O: none (pure)
// Run: zig build test -Dfile=ru-huma-dist-test.zig
// ===================================================================
const std = @import("std"); const dist = @import("ru-huma-dist.zig");
fn sample(prn: *std.Random.DefaultPrng, lo: u64, hi: u64, fact: f64, plong: f64) u64 { const rnd = prn.random(); return dist.pick(rnd.float(f64), rnd.float(f64), lo, hi, fact, plong); }
test "every delay stays inside the configured range, for any factor" { var prn = std.Random.DefaultPrng.init(7); for ([_]f64{ 0.5, 1.0, 1.4, 3.0 }) |fact| { var idx: usize = 0; while (idx < 5000) : (idx += 1) { const val = sample(&prn, 90, 260, fact, 0.2); try std.testing.expect(val >= 90 and val <= 260); } } }
test "about 20% are long, the distribution is spread, skewed right and never fixed" { var prn = std.Random.DefaultPrng.init(11); const cnt: usize = 40000; var sum: f64 = 0; var sq: f64 = 0; var longz: usize = 0; const vals = try std.testing.allocator.alloc(u64, cnt); defer std.testing.allocator.free(vals); for (vals, 0..) |*slot, idx| { _ = idx; slot.* = sample(&prn, 100, 3000, 1.0, 0.2); const flt: f64 = @floatFromInt(slot.*); sum += flt; sq += flt * flt; if (slot.* > 900) longz += 1; } const mean = sum / @as(f64, cnt); const varz = sq / @as(f64, cnt) - mean * mean; const cov = @sqrt(varz) / mean; std.mem.sort(u64, vals, {}, std.sort.asc(u64)); const med: f64 = @floatFromInt(vals[cnt / 2]); const shar = @as(f64, @floatFromInt(longz)) / @as(f64, cnt); try std.testing.expect(shar > 0.10 and shar < 0.35); try std.testing.expect(cov > 0.5); try std.testing.expect(mean > med); }
test "persona is fixed for an account on a day, drifts slowly, differs between accounts, stays bounded" { const aaa = dist.hashOf("acct-one"); const bbb = dist.hashOf("acct-two"); const day: i64 = 20600; try std.testing.expectEqual(dist.persona(aaa, day).speed, dist.persona(aaa, day).speed); var diff: usize = 0; var dayz: i64 = day; while (dayz < day + 90) : (dayz += 1) { const cur = dist.persona(aaa, dayz); const nxt = dist.persona(aaa, dayz + 1); try std.testing.expect(@abs(cur.speed - nxt.speed) < 0.02); try std.testing.expect(cur.speed >= 0.80 and cur.speed <= 1.20); try std.testing.expect(cur.plong >= 0.15 and cur.plong <= 0.25); if (@abs(cur.speed - dist.persona(bbb, dayz).speed) > 0.001) diff += 1; } try std.testing.expect(diff > 60); }
test "fatigue starts at 1, only grows, and is capped" { try std.testing.expectEqual(@as(f64, 1.0), dist.fatigue(0)); var prev: f64 = 1.0; var step: u64 = 0; while (step < 24 * 3600000) : (step += 600000) { const cur = dist.fatigue(step); try std.testing.expect(cur >= prev and cur <= 1.3001); prev = cur; } }
test "a slower persona waits longer and thinks more; a degenerate range returns its floor" { var prn = std.Random.DefaultPrng.init(3); var fast: f64 = 0; var slow: f64 = 0; var idx: usize = 0; while (idx < 8000) : (idx += 1) { fast += @floatFromInt(sample(&prn, 100, 3000, 0.85, 0.15)); slow += @floatFromInt(sample(&prn, 100, 3000, 1.15, 0.25)); } try std.testing.expect(slow > fast * 1.1); try std.testing.expectEqual(@as(u64, 50), dist.pick(0.5, 0.5, 50, 50, 1.0, 0.2)); }
